export function useAlerts(userId?: string) {
  const { data: alerts, execute: fetchAlerts } = useAsyncState(
    useCallback(async () => {
      if (!userId) return [];
      const res = await fetch('/api/alerts', { headers: { 'x-user-id': userId } });
      if (!res.ok) throw new Error('Failed to fetch alerts');
      const data = await res.json();
      return data.alerts;
    }, [userId])
  );

  useEffect(() => {
    fetchAlerts();
  }, [fetchAlerts]);

  // createAlert などその他のメソッド...
  return { alerts: alerts || [], fetchAlerts, createAlert };
}

const { data: userData, execute: fetchUserData } = useAsyncState(
